import math
from itertools import product

import numpy as np
import pandas as pd
from joblib import Parallel, delayed
from sklearn.cluster import DBSCAN


def create_weighted_distance(w: float):
    weight_y = 2.0 - w

    def distance(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return math.sqrt((w * dx) ** 2 + (weight_y * dy) ** 2)

    return distance


def greedy_match_centroids(centroids: np.ndarray, experts: np.ndarray, max_dist: float = 100.0):
    if centroids.size == 0 or experts.size == 0:
        return []
    diffs = centroids[:, None, :] - experts[None, :, :]
    dists = np.sqrt(np.sum(diffs ** 2, axis=2))
    flat = dists.ravel()
    order = np.argsort(flat)
    used_centroids = set()
    used_experts = set()
    matches = []
    num_experts = dists.shape[1]
    for idx in order:
        dist = flat[idx]
        if dist > max_dist:
            break
        i = idx // num_experts
        j = idx % num_experts
        if i in used_centroids or j in used_experts:
            continue
        used_centroids.add(i)
        used_experts.add(j)
        matches.append(dist)
    return matches


def evaluate_combo(min_samples, eps, w, image_data):
    metric = create_weighted_distance(w)
    f1_total = 0.0
    delta_values = []

    for citsci_pts, expert_pts in image_data:
        if citsci_pts is None or len(citsci_pts) == 0:
            f1_total += 0.0
            continue

        clustering = DBSCAN(eps=eps, min_samples=min_samples, metric=metric)
        labels = clustering.fit_predict(citsci_pts)
        unique_labels = [l for l in set(labels) if l != -1]
        if not unique_labels:
            f1_total += 0.0
            continue

        centroids = np.vstack([citsci_pts[labels == l].mean(axis=0) for l in unique_labels])
        matches = greedy_match_centroids(centroids, expert_pts, max_dist=100.0)
        if not matches:
            f1_total += 0.0
            continue

        precision = len(matches) / len(centroids)
        recall = len(matches) / len(expert_pts)
        if precision + recall == 0:
            f1 = 0.0
        else:
            f1 = 2 * precision * recall / (precision + recall)
        f1_total += f1
        delta_values.append(float(np.mean(matches)))

    num_images = len(image_data)
    f1_avg = f1_total / num_images if num_images else 0.0
    if delta_values:
        delta_avg = float(np.mean(delta_values))
    else:
        delta_avg = float('nan')

    return {
        "F1": f1_avg,
        "delta": delta_avg,
        "min_samples": int(min_samples),
        "epsilon": int(eps),
        "shape_weight": float(w),
    }


def pareto_frontier(results):
    frontier = []
    for i, r in enumerate(results):
        dominated = False
        for j, s in enumerate(results):
            if i == j:
                continue
            if s["F1"] >= r["F1"] and s["delta"] <= r["delta"]:
                if s["F1"] > r["F1"] or s["delta"] < r["delta"]:
                    dominated = True
                    break
        if not dominated:
            frontier.append(r)
    return frontier


def main():
    citsci = pd.read_csv("/root/data/citsci_train.csv", usecols=["file_rad", "x", "y"]).dropna()
    expert = pd.read_csv("/root/data/expert_train.csv", usecols=["file_rad", "x", "y"]).dropna()

    citsci_groups = {
        file_rad: grp[["x", "y"]].to_numpy(dtype=float)
        for file_rad, grp in citsci.groupby("file_rad")
    }
    expert_groups = {
        file_rad: grp[["x", "y"]].to_numpy(dtype=float)
        for file_rad, grp in expert.groupby("file_rad")
    }

    image_data = []
    for file_rad, expert_pts in expert_groups.items():
        citsci_pts = citsci_groups.get(file_rad)
        image_data.append((citsci_pts, expert_pts))

    min_samples_grid = list(range(3, 10))
    epsilon_grid = list(range(4, 25, 2))
    shape_weight_grid = [round(0.9 + 0.1 * i, 1) for i in range(11)]

    param_grid = list(product(min_samples_grid, epsilon_grid, shape_weight_grid))

    results = Parallel(n_jobs=-1, verbose=10)(
        delayed(evaluate_combo)(m, e, w, image_data) for m, e, w in param_grid
    )

    filtered = [r for r in results if r["F1"] > 0.5 and math.isfinite(r["delta"])]
    pareto = pareto_frontier(filtered)

    pareto_sorted = sorted(pareto, key=lambda r: (-r["F1"], r["delta"], r["min_samples"], r["epsilon"], r["shape_weight"]))

    output_rows = []
    for r in pareto_sorted:
        output_rows.append({
            "F1": round(r["F1"], 5),
            "delta": round(r["delta"], 5),
            "min_samples": int(r["min_samples"]),
            "epsilon": int(r["epsilon"]),
            "shape_weight": round(r["shape_weight"], 1),
        })

    out_df = pd.DataFrame(output_rows, columns=["F1", "delta", "min_samples", "epsilon", "shape_weight"])
    out_df.to_csv("/root/pareto_frontier.csv", index=False)


if __name__ == "__main__":
    main()
